-- =====================================================================
-- M15_22 行业模板种子数据填充脚本（T15.33，V3.5 对齐，v1.34 新增）
-- 版本：v1.0  日期：2026-09-17
-- 依据：《SaaS 平台需求草稿_最终定稿版 V3.5》第十六章「行业模板与初始化机制」
--       《资金管控系统开发任务文档》v1.24 T15.33~T15.34
--       `docs/最新整理好的需求/初始化项目清单_上海.xlsx`（23 个二级行业 × 132 个真实服务项目）
-- 前置依赖：M15_02（industry_template + industry_role_map 建表 + 4 个既有行业）
-- 规范：
--   1. 【幂等】INSERT IGNORE + uk_industry_code / uk_industry_bizrole 保护，可重复执行
--   2. 【存量兼容】既有 board_game / gym / spa 三个行业仅 UPDATE preset_config（保留 industry_code 不变，
--      避免破坏 sys_tenant.industry 外键引用）；既有 market 因 V3.5 §10 排除零售/生鲜，SET status=1 停用不删除
--   3. 【23 行业口径】休闲娱乐 6 + 生活服务 7 + 运动健身 7 + 专业工作室 3 = 23（V3.5 §16 + 任务文档 v1.24 T15.33）
--   4. preset_config JSON 结构：{ category, service_categories[], settle_rule, units[], projects[{name,reference_price,duration,sample_merchant,feature}] }
--   5. projects 每行业取 Excel 前 5~7 条（大众点评上海公开团购真实数据）
--   6. industry_role_map 每行业 3 条：boss/salesman/customer 标准角色 + 行业化业务角色显示名
-- =====================================================================

SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;

-- ---------------------------------------------------------------------
-- 1. 存量兼容：market（买菜/生鲜）停用（V3.5 §10 明确排除零售/生鲜）
--    保留 industry_code 与既有 sys_tenant.industry 引用，仅隐藏下拉框
-- ---------------------------------------------------------------------
UPDATE `industry_template` SET `status` = '1', `update_by` = 'admin', `update_time` = NOW(),
  `remark` = '【V3.5 停用】零售/生鲜不在小微版适用范围（V3.5 §10），保留数据兼容既有租户'
WHERE `industry_code` = 'market';

-- ---------------------------------------------------------------------
-- 2. 23 个二级行业模板（INSERT IGNORE 幂等 + 后续 UPDATE 补 preset_config）
